local ServiceCollection = require(script.Parent.Parent.Parent.Core.DependencyInjection.ServiceCollection)
local serviceDescriptorsProvider = require(script.ServiceDescriptorsProvider)
local LoggerManger: ILoggerManager = require(game.ReplicatedStorage.Packages.LoggerManager)
local logger = LoggerManger.GetLogger("TangSeng")

-- 遍历root内 `service`的模块, 根据配置注册服务

return function(
	root: Instance,
	lifeTimes: { [string]: string }?,
	hostBuilderContext: IHostBuilderContext,
	serviceCollection: ServiceCollection.Type
)
	local children = root:GetDescendants()
	lifeTimes = lifeTimes or {}

	for _, child in ipairs(children) do
		if child:IsA("ModuleScript") then
			local serviceDescriptor = serviceDescriptorsProvider(child, lifeTimes, hostBuilderContext)
			if not serviceDescriptor then
				continue
			end
			serviceCollection:Add(serviceDescriptor)
			logger.verbose(function(name)
				print(name, `加载服务描述`, serviceDescriptor.ServiceType)
			end)
		end
	end
end
